      mainEntity: [
        {
          "@type": "Question",
          name: "How much VRAM do I need for local LLMs?",
          acceptedAnswer: {
            "@type": "Answer",
            text: "12 GB handles dense models up to about 14B at Q4 quantization, 16 GB fits mid-size models such as gpt-oss-20b (OpenAI states it runs within 16 GB), and 24 GB fits dense ~32B models at Q4 (estimates). 70B-class models need about 43 GB for weights at Q4, so two 24 GB GPUs or a 48 GB-class card. Use the [VRAM calculator](/local-llms/vram-calculator-local-llm) for exact fits.",
          },
        },
        {
          "@type": "Question",
          name: "What is the best GPU for local LLMs in 2026?",
          acceptedAnswer: {
            "@type": "Answer",
            text: "There is no single best GPU: choose by VRAM tier, then compare live prices. For 7B–14B models a 12–16 GB card is enough, and the RTX 5070 Ti (176.9 tok/s) is within about 5% of the RTX 4090 (186.2 tok/s) in developer-reported 7B tests. For 30B-class models you need 24 GB, and the RTX 5090 offers 32 GB. Prices are far above MSRP in the tracked data, so check current listings.",
          },
        },
        {
          "@type": "Question",
          name: "Is the RTX 4090 still worth buying for local LLMs?",
          acceptedAnswer: {
            "@type": "Answer",
            text: "It depends on the price you can get. The RTX 4090 offers 24 GB and 186.2 tok/s in the 7B test, but the InsiderLLM tracker lists new cards at $2,000–3,000 (MSRP $1,599) and used sold listings at $2,575–3,010. A used RTX 3090 (about $1,500–1,725, 158.2 tok/s) gives the same 24 GB for less, with slower prompt processing. The RTX 4090 makes sense mainly if you need that faster prompt processing.",
          },
        },
        {
          "@type": "Question",
          name: "Is a used RTX 3090 still a good choice for local LLMs?",
          acceptedAnswer: {
            "@type": "Answer",
            text: "It is the lowest-priced 24 GB NVIDIA option in the tracked data (about $1,500–1,725 in sold listings, US eBay sales, 13–23 November 2026) and reaches 158.2 tok/s on the 7B test, about 85% of an RTX 4090. Its prompt processing is less than half (5,175 versus 11,993 tok/s), and used cards may have no warranty and carry wear risk; read [Used GPUs for Local LLMs](/local-llms/used-gpus-for-local-llms) first.",
          },
        },
        {
          "@type": "Question",
          name: "Should I buy an AMD GPU for local LLMs?",
          acceptedAnswer: {
            "@type": "Answer",
            text: "It can work for token generation, with trade-offs. On the Vulkan scoreboard the RX 7900 XTX (24 GB) generates 182.6 tok/s versus 188.0 for an RTX 4090 but processes prompts about 2.5 times slower. Software setup differs by backend (ROCm, Vulkan), so check the current llama.cpp and Ollama notes for your exact card before buying.",
          },
        },
        {
          "@type": "Question",
          name: "What is the best GPU for running 70B models locally?",
          acceptedAnswer: {
            "@type": "Answer",
            text: "Two 24 GB GPUs (48 GB combined) are the common consumer route: llama3.3:70b is a 43 GB download per Ollama, which leaves little room for context. A single 24 GB or 32 GB card cannot hold it without much heavier quantization and quality loss. Dual-GPU speed depends on software and interconnect, so no figure is given here; see [Multi-GPU Local LLMs](/local-llms/multi-gpu-local-llms).",
          },
        },
        {
          "@type": "Question",
          name: "Does more VRAM make a GPU faster for local LLMs?",
          acceptedAnswer: {
            "@type": "Answer",
            text: "No. VRAM sets which models fit; once a model fits, speed follows memory bandwidth and compute rather than capacity. In the 7B test the 24 GB RTX 3090 (158.2 tok/s) is slower than the 16 GB RTX 5080 (182.0 tok/s).",
          },
        },
        {
          "@type": "Question",
          name: "What GPU has 32 GB VRAM for local LLMs?",
          acceptedAnswer: {
            "@type": "Answer",
            text: "The RTX 5090 (32 GB GDDR7) is the GeForce card with the largest VRAM in these sources; it generates 290.0 tok/s on the 7B test. NVIDIA lists 575 W total graphics power and 1,000 W required system power for it, and retail prices around $4,500–4,700 were tracked against a $1,999 MSRP. The extra 8 GB over 24 GB mainly buys higher-fidelity quantization or longer context on ~32B models (estimate); 70B-class models still need about 43 GB.",
          },
        },
      ],
