            text: "Elige una GPU para LLMs locales primero por nivel de VRAM (12, 16, 24 o 32 GB) y después por velocidad de memoria y precio actual, porque una RTX 5070 Ti de 16 GB genera 176.9 tok/s frente a 186.2 tok/s de una RTX 4090 de 24 GB en pruebas 7B de llama.cpp reportadas por desarrolladores.",
