            q: "كم VRAM أحتاج لنماذج LLM المحلية؟",
            a: "تتسع 12 GB لنماذج كثيفة حتى نحو 14B بتكميم Q4، وتناسب 16 GB نماذج متوسطة مثل gpt-oss-20b (تذكر OpenAI أنه يعمل ضمن 16 GB)، وتناسب 24 GB نماذج كثيفة بحجم نحو 32B بصيغة Q4 (تقديرات). وتحتاج نماذج فئة 70B إلى نحو 43 GB للأوزان بصيغة Q4، أي بطاقتي GPU بسعة 24 GB أو بطاقة من فئة 48 GB. استخدم [حاسبة VRAM](/ar/local-llms/vram-calculator-local-llm) لمعرفة الملاءمة بدقة.",
