      mainEntity: [
        {
          "@type": "Question",
          name: "Wie viel VRAM benötige ich für lokale LLMs?",
          acceptedAnswer: {
            "@type": "Answer",
            text: "12 GB bewältigen dichte Modelle bis etwa 14B bei Q4-Quantisierung, 16 GB passen für mittelgroße Modelle wie gpt-oss-20b (OpenAI gibt an, dass es mit 16 GB läuft), und 24 GB passen für dichte ~32B-Modelle bei Q4 (Schätzungen). Modelle der 70B-Klasse brauchen bei Q4 etwa 43 GB für die Gewichte, also zwei 24-GB-GPUs oder eine Karte der 48-GB-Klasse. Genaue Werte liefert der [VRAM-Rechner](/de/local-llms/vram-calculator-local-llm).",
          },
        },
        {
          "@type": "Question",
          name: "Welche ist 2026 die beste GPU für lokale LLMs?",
          acceptedAnswer: {
            "@type": "Answer",
            text: "Die eine beste GPU gibt es nicht: Wählen Sie nach VRAM-Stufe und vergleichen Sie dann aktuelle Preise. Für 7B–14B-Modelle reicht eine Karte mit 12–16 GB, und die RTX 5070 Ti (176,9 Token/s) liegt in von Entwicklern gemeldeten 7B-Tests etwa 5 % hinter der RTX 4090 (186,2 Token/s). Für Modelle der 30B-Klasse brauchen Sie 24 GB, und die RTX 5090 bietet 32 GB. Die Preise liegen in den erfassten Daten weit über der UVP; prüfen Sie daher aktuelle Listings.",
          },
        },
        {
          "@type": "Question",
          name: "Lohnt sich die RTX 4090 für lokale LLMs noch?",
          acceptedAnswer: {
            "@type": "Answer",
            text: "Das hängt vom erzielbaren Preis ab. Die RTX 4090 bietet 24 GB und 186,2 Token/s im 7B-Test, doch der InsiderLLM-Tracker listet neue Karten bei 2.000–3.000 US-$ (UVP 1.599 US-$) und abgeschlossene Gebrauchtverkäufe bei 2.575–3.010 US-$. Eine gebrauchte RTX 3090 (etwa 1.500–1.725 US-$, 158,2 Token/s) bietet dieselben 24 GB günstiger, bei langsamerer Prompt-Verarbeitung. Die RTX 4090 lohnt sich vor allem, wenn Sie diese schnellere Prompt-Verarbeitung brauchen.",
          },
        },
        {
          "@type": "Question",
          name: "Ist eine gebrauchte RTX 3090 für lokale LLMs noch eine gute Wahl?",
          acceptedAnswer: {
            "@type": "Answer",
            text: "Sie ist in den erfassten Daten die günstigste 24-GB-NVIDIA-Option (etwa 1.500–1.725 US-$ bei abgeschlossenen Verkäufen, Stand 2026-11-23) und erreicht im 7B-Test 158,2 Token/s, rund 85 % einer RTX 4090. Ihre Prompt-Verarbeitung liegt bei weniger als der Hälfte (5.175 gegenüber 11.993 Token/s), und gebrauchte Karten haben womöglich keine Garantie und tragen Verschleißrisiko; lesen Sie zuerst [Gebrauchte GPUs für lokale LLMs](/de/local-llms/used-gpus-for-local-llms).",
          },
        },
        {
          "@type": "Question",
          name: "Sollte ich eine AMD-GPU für lokale LLMs kaufen?",
          acceptedAnswer: {
            "@type": "Answer",
            text: "Für die Token-Generierung kann das funktionieren, mit Abstrichen. In der Vulkan-Tabelle erzeugt die RX 7900 XTX (24 GB) 182,6 Token/s gegenüber 188,0 bei einer RTX 4090, verarbeitet Prompts aber etwa 2,5-mal langsamer. Die Software-Einrichtung unterscheidet sich je nach Backend (ROCm, Vulkan); prüfen Sie vor dem Kauf die aktuellen Hinweise von llama.cpp und Ollama für Ihre genaue Karte.",
          },
        },
        {
          "@type": "Question",
          name: "Welche GPU eignet sich am besten für die lokale Ausführung von 70B-Modellen?",
          acceptedAnswer: {
            "@type": "Answer",
            text: "Zwei 24-GB-GPUs (48 GB kombiniert) sind der übliche Weg für Privatanwender: llama3.3:70b hat laut Ollama 43 GB Download, was wenig Platz für Kontext lässt. Eine einzelne 24-GB- oder 32-GB-Karte fasst es nur mit deutlich stärkerer Quantisierung und Qualitätsverlust. Die Geschwindigkeit mit zwei GPUs hängt von Software und Verbindung ab; daher nennen wir keinen Wert, siehe [Multi-GPU für lokale LLMs](/de/local-llms/multi-gpu-local-llms).",
          },
        },
        {
          "@type": "Question",
          name: "Macht mehr VRAM eine GPU für lokale LLMs schneller?",
          acceptedAnswer: {
            "@type": "Answer",
            text: "Nein. Der VRAM bestimmt, welche Modelle passen; sobald ein Modell passt, folgt die Geschwindigkeit Speicherbandbreite und Rechenleistung, nicht der Kapazität. Im 7B-Test ist die RTX 3090 mit 24 GB (158,2 Token/s) langsamer als die RTX 5080 mit 16 GB (182,0 Token/s).",
          },
        },
        {
          "@type": "Question",
          name: "Welche GPU hat 32 GB VRAM für lokale LLMs?",
          acceptedAnswer: {
            "@type": "Answer",
            text: "Die RTX 5090 (32 GB GDDR7) ist in diesen Quellen die GeForce-Karte mit dem größten VRAM; sie erzeugt im 7B-Test 290,0 Token/s. NVIDIA nennt dafür 575 W Total Graphics Power und 1.000 W erforderliche Systemleistung; erfasst wurden Handelspreise um 4.500–4.700 US-$ bei einer UVP von 1.999 US-$. Die zusätzlichen 8 GB gegenüber 24 GB bringen vor allem genauere Quantisierung oder mehr Kontext bei ~32B-Modellen (Schätzung); Modelle der 70B-Klasse brauchen weiterhin etwa 43 GB.",
          },
        },
      ],
