          "**電力と冷却の計画を省く。** NVIDIAはRTX 5090の総グラフィックス電力を575 Wとしています。カードメーカーの電源・ケーブル・エアフローの指示を確認し、[ローカルLLMの消費電力](/ja/local-llms/local-llm-power-consumption)も参照してください。",
